                case RecordTypeInts.XCLL:
                {
                    _XCLLLocation = (stream.Position - offset);
                    return (int)Cell_FieldIndex.XCLL;
                }
                case RecordTypeInts.XCRI:
                {
                    _XCRILocation = (stream.Position - offset);
                    _XCRILengthOverride = lastParsed.LengthOverride;
                    if (lastParsed.LengthOverride.HasValue)
                    {
                        stream.Position += lastParsed.LengthOverride.Value;
                    }
                    return (int)Cell_FieldIndex.XCRI;
                }
                case RecordTypeInts.XCRP:
                {
                    _XCRPLocation = (stream.Position - offset);
                    return (int)Cell_FieldIndex.XCRP;
                }
                case RecordTypeInts.XILW:
                {
