                }
                case RecordTypeInts.XISR:
                {
                    _XISRLocation = (stream.Position - offset);
                    return (int)Cell_FieldIndex.XISR;
                }
                case RecordTypeInts.XCLC:
                {
                    _XCLCLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Cell_FieldIndex.XCLC;
                }
                case RecordTypeInts.NAM2:
                {
                    _NAM2Location = (stream.Position - offset);
                    return (int)Cell_FieldIndex.NAM2;
                }
                case RecordTypeInts.NAM3:
                {
                    _NAM3Location = (stream.Position - offset);
